const fs = require('node:fs');
const path = require('node:path');

const read = name => fs.readFileSync(path.join(__dirname, '..', name), 'utf8');
const documents = Object.fromEntries(
  ['learner-profile.md', 'progress.md', 'sessions.md', 'README.md', 'AGENTS.md']
    .map(name => ['../' + name, read(name)])
);
const evidence = Object.fromEntries(read('evidence.jsonl').split(/\r?\n/)
  .filter(line => line.trim())
  .map(line => {
    const record = JSON.parse(line);
    return [record.id, record];
  }));

fs.writeFileSync(path.join(__dirname, 'records-data.js'),
  '// Generated by refresh-records.cjs from the local learning records.\n' +
  'window.SPANISH_MASTERY_RECORDS = ' + JSON.stringify({documents, evidence}, null, 2) + ';\n');
